def clean_title(title):
    if not title:
        return ""
    title = str(title).strip()
    title = re.sub(r"\s*\d+$", "", title)
    return title.strip()


def clean_text(text):
    if not text:
        return ""

    text = str(text).strip()
    text = re.sub(r"\[\d+\]", "", text)
    text = re.sub(r"\(\d{4}(-\d{4})?\)", "", text)
    text = re.sub(r"\s+", " ", text)

    return text.strip()


def safe_json_extract(raw_text):

    match = re.search(r"```(?:json)?\s*(.*?)\s*```", raw_text, re.DOTALL)

    if match:
        raw_text = match.group(1)

    try:
        obj = json.loads(raw_text)
    except:
        obj = {}

    for key in ["Predicate mapping", "Predicate_mapping"]:
        if key in obj:
            obj = obj[key]

    obj.pop("Explanation", None)

    return obj

def sanitize_rows(rows):
    cleaned = []

    for r in rows:
        clean_r = {}

        for k, v in r.items():

            # convert dict → string
            if isinstance(v, dict):
                v = json.dumps(v, ensure_ascii=False)

            # convert list → string
            elif isinstance(v, list):
                v = " | ".join(map(str, v))

            clean_r[k] = v

        cleaned.append(clean_r)

    return cleaned

def extract_only_triples(text):

    pattern = re.findall(r"\((.*?)\s*,\s*(P\d+)\s*,\s*(.*?)\)", text)

    triples = []

    for s, p, o in pattern:

        triples.append({
            "subject": s.strip(),
            "predicate": p.strip(),
            "object": o.strip()
        })

    return triples

