def get_mapping(new_table, new_text, new_title):

    prompt_text = f"""
        You are an AI assistant that maps table columns to knowledge graph predicates.

        Allowed predicates:
        {chr(10).join([f"- {k}: {v}" for k, v in allowed_predicates.items()])}

        --------------------------------------------------
        Example 1 (Ronda Rousey)
        Table columns:
        {chr(10).join([f"- {k}: {v}" for k, v in example_table_1.items()])}
        Text:
        {example_text_1}
        Relevant entity: Ronda Rousey (may appear as subject or object)
        Explanation:
        - "Année":
          - In english: Year Column.
          - Table: Lists years like 2013, 2014, 2015, 2016, 2017.
          - Text: Mentions Ronda’s career timeline and events in specific years.
          - Reasoning → These values represent years in which certain events or rankings occurred in Ronda's career. Since "Année" refers to year, this column does not directly map to any of the allowed predicates → mapped to None.
        - "Rang":
          - In english: Ranking Column.
          - Table: Lists rankings like 1, 3, Non classée, 18.
          - Text: Mentions Ronda’s various rankings throughout her career in MMA.
          - Reasoning → The rankings represent Ronda's performance in different tournaments or competitions. Since the "Rang" column refers to ranking, this column → mapped to P1352 predicate which is defined as "The ordinal or ranking position of the subject in a list, competition, or group".
        Predicate mapping:
        {json.dumps(example_mapping_1, indent=2)}

        --------------------------------------------------
        Example 2 (Christiane Taubira)
        Table columns:
        {chr(10).join([f"- {k}: {v}" for k, v in example_table_2.items()])}
        Text:
        {example_text_2}
        Relevant entity: Christiane Taubira (may appear as subject or object)
        Explanation:
        - "Année", "Parti", "Circonscription", "Issue":
          - In english: Year, Party, Constituency, Outcome columns.
          - Table: Contains placeholders, party names, constituency names, or election outcomes.
          - Text: Refers to general information about elections, candidate affiliation, locations, or results.
          - Reasoning → These columns provide contextual or descriptive information, but none of their values directly match any allowed predicates. Therefore, all these columns are mapped to None.
        - "%":
          - In english: Percentage Column.
          - Table: Lists vote percentages like "42,81", "55,47", "49,10", "64,76".
          - Text: Represents the share of votes each candidate received in elections.
          - Reasoning → Since the values are numeric percentages representing votes received, this column maps to P1111 predicate, which is defined as "The number or share of votes the subject received in an election or vote".
        - "Rang":
          - In english: Ranking Column.
          - Table: Lists rankings like "50,44", "65,27", "36,67", "63,41".
          - Text: Refers to the ranking or position of the candidate in the election results.
          - Reasoning → Rankings indicate ordinal positions of the subject in a competition or event. Therefore, this column maps to P1352 predicate, which is defined as "The ordinal or ranking position of the subject in a list, competition, or group".
        Predicate mapping:
        {json.dumps(example_mapping_2, indent=2)}

        --------------------------------------------------
        Example 3 (Reine)
        Table columns:
        {chr(10).join([f"- {k}: {v}" for k, v in example_table_3.items()])}
        Text:
        {example_text_3}
        Relevant entity: Reine (may appear as subject or object)
        Explanation:
        - "Époux", "Ascendance", "Descendance", "Titres", "Armoiries":
          - In english: Spouse, Ancestry, Descendants, Titles, Coat of Arms columns.
          - Table: Contains information about spouses (names and marriage years), family lineage, titles held, and heraldic images.
          - Text: Provides historical and genealogical context about the duchesses of Brittany, their family connections, and visual armorial representations.
          - Reasoning → These columns describe contextual, relational, or visual information that is not directly covered by any allowed predicate. Therefore, all these columns are mapped to None.
        - "Nom":
          - In english: Name Column.
          - Table: Lists the names of duchesses like "Béatrice d'Angleterre(1242-1275)", "Marie de Limoges(1260-1291)", etc.
          - Text: Mentions the names of the princesses/duchesses of Brittany in historical context.
          - Reasoning → Since this column lists noble titles or royal names, it corresponds to the P97 predicate, which is defined as "noble title: A hereditary, honorific, or royal rank held by the subject". Therefore, "Nom" is mapped to P97.
        Predicate mapping:
        {json.dumps(example_mapping_3, indent=2)}

        --------------------------------------------------
        Example 4 (Caroline Garcia)
        Table columns:
        {chr(10).join([f"- {k}: {v}" for k, v in example_table_4.items()])}
        Text:
        {example_text_4}
        Relevant entity: Caroline Garcia (may appear as subject or object)
        Explanation:
        - "#", "Date", "($)", "Surface", "Résultat", "Partenaire", "Ultimes adversaires", "Score", "":
          - In english: Index, Date, Prize money, Surface, Result, Partner, Opponents, Score, Miscellaneous.
          - Table: Provide match details such as dates, surfaces, results, partners, opponents, and scores.
          - Text: Describes match outcomes and tournament progress of Caroline Garcia.
          - Reasoning → These columns contain contextual or statistical match information that does not match any allowed predicate. Therefore, they are mapped to None.
        - "Nom de l'édition":
          - In english: Tournament name.
          - Table: Lists events like "BNP Paribas WTA Finals Singapour".
          - Text: Refers to tournaments in which Caroline Garcia participated.
          - Reasoning → This column represents events the subject took part in, corresponding to predicate P1344 (participant in).
        Predicate mapping:
        {json.dumps(example_mapping_4, indent=2)}

        --------------------------------------------------
        New Table - {new_title}
        Table columns:
        {chr(10).join([f"- {k}: {v}" for k, v in new_table.items()])}
        Text:
        {new_text or "No additional text provided."}
        Relevant entity: {new_title} (may appear as subject or object)

        Instructions for mapping:
        - Columns and values may be in any language. Use the column meaning and values, along with text context, to determine the correct predicate.
        - If a column header is unclear, rely on values and context to map it appropriately.
        - Map to **None** if no clear predicate is found.
        - Return the mapping in JSON format only (no extra text).
        """

    # Send request to OpenAI ChatCompletion API
    llm_answer = client.chat.completions.create(
        model="gpt-4o",
        messages=[{"role": "user", "content": prompt_text}],
        max_tokens=512,
        temperature=0,
    )
    raw_output = llm_answer.choices[0].message.content

    return safe_json_extract(raw_output)


# ============================================================
# STAGE 2: CODE 1
# SUBJECT = DOCUMENT TITLE
# ============================================================

def run_code1(doc_id, title, table_data, mapping):

    rows = []

    for col, values in table_data.items():

        predicate = mapping.get(col)

        if not predicate or predicate == "None":
            continue

        if not isinstance(values, list):
            values = [values]

        for val in values:

            val = clean_text(val)

            if not val:
                continue

            rows.append({
                "document_id": doc_id,
                "mode": "CODE1",
                "subject": title,
                "predicate": predicate,
                "object": val
            })

    return rows


