def run_code2(doc_id, table_data, column_mapping, related_text):

    results = []

    prompt_text_stage2 = f"""
You are an AI assistant for knowledge graph construction. 

You are given:
1. A table with column headers and multiple rows of data.
2. Related contextual text describing the table.
3. Allowed predicates with their description.
4. Mapping of table columns to allowed predicates.

Your tasks:
1. For each row, identify which column should be the **subject** (main entity of the row).
2. Identify which columns can become **object entities** based on the text.
3. Generate all possible valid triples for each row in the format: 
   (subject, predicate, object)
4. Only use allowed predicates.
5. If a column does not map to a predicate, ignore it for triples.
6. Ensure that the subject reflects the main entity that the row describes.
7. Output triples for all rows in the same table.

---

**Input Format:**

Table:
{json.dumps(table_data, indent=2, ensure_ascii=False)}

Related Text:
{related_text}

Allowed Predicates:
{json.dumps(allowed_predicates, indent=2, ensure_ascii=False)}

Column → Predicate Mapping:
{json.dumps(column_mapping, indent=2, ensure_ascii=False)}

---

**Output Format:**

Triples:
(subject, predicate, object)
"""

    # LLM call
    llm_answer = client.chat.completions.create(
        model="gpt-4o",
        messages=[{"role": "user", "content": prompt_text_stage2}],
        max_tokens=512,
        temperature=0,
    )
    outputs = llm_answer.choices[0].message.content

    # Store raw output (or parsed later)
    results.append({
        "doc_id": doc_id,
        "table": table_data,
        "triples": outputs
    })

    return results


# ============================================================
# FULL PIPELINE
# ============================================================

def run_system(input_file):

    print(f"\nLoading file: {input_file}")

    with open(input_file, "r", encoding="utf-8") as f:
        json_data = json.load(f)
      
    # --------------------------------------------------------
    # LOOP THROUGH INPUT DATA
    # --------------------------------------------------------

    for doc_entry in tqdm(json_data):

        doc_id = doc_entry.get("id")

        table_obj = doc_entry.get("table", {})
        table_data = table_obj.get("tableData", {})

        if not table_data:
            continue

        title = clean_title(doc_entry.get("title", ""))

        text = doc_entry.get("full_text", "")

        print(f"\nProcessing table from doc id: {doc_id}")

        # ====================================================
        # STAGE 1: PREDICATE MAPPING
        # ====================================================
        try:
          mapping = get_mapping(table_data, text, title)
        except Exception as e:
          print("Mapping error:", e)
          continue

        # ====================================================
        # STAGE 2: TRIPLE GENERATION
        # ====================================================
        if not title.lower().startswith("liste"):
            rows = run_code1(doc_id, title, table_data, mapping)
        else:
            rows = run_code2(doc_id, table_data, mapping, text)
            rows = extract_only_triples(rows[0]["triples"])
            for r in rows:
              r["document_id"] = doc_id

        df = pd.DataFrame(rows)

        if not df.empty:
            df = sanitize_rows(rows)
            df = pd.DataFrame(df)

            df = df[["document_id", "subject", "predicate", "object"]]

            df.drop_duplicates(
                subset=["document_id", "subject", "predicate", "object"],
                inplace=True
            )
            print("\n================ FINAL RDF TRIPLES ================\n")
            print(df.to_string(index=False))

            print(f"\nTotal triples generated: {len(df)}")

        else:
            print("\n No triples generated for this table.")


if __name__ == "__main__":

    input_path = "cleaned_data/female_celebrity_data.json"

    run_system(input_path)